/**
 * The pinned SimulationCraft profile and environment of each specialization (SIMC-FB-A;
 * agent/architecture.md "Owner decision (2026-11-06): SimC profile fallback").
 *
 * Generated by `scripts/authority/extract-simc-profile-environment.mjs` from the pinned commits. The
 * APL artifacts hold no environment, so this is where it is recorded. It is not an execution profile:
 * `src/simulation/execution-profiles.ts` says how to RUN a simulation, and this says what the pinned
 * profile's encounter IS. Nothing here is a fact of a real fight.
 *
 * A model appears only when its cited engine lines and its profile option lines read the same as the
 * analyzer pin's, so `models` lists the game builds this environment is proven at. It says nothing
 * about the APL, which stays at the analyzer pin.
 *
 * A file that does not validate stops the process at load, like every other runtime artifact.
 */

import { z } from "zod";

import artifact from "./simc-profile-environment.json";

const sha256 = z.string().regex(/^[0-9a-f]{64}$/);
const commit = z.string().regex(/^[0-9a-f]{40}$/);

const semanticSchema = z
  .object({
    semanticId: z.string().min(1),
    sourcePath: z.string().min(1),
    sourceSha256: sha256,
    startLine: z.number().int().positive(),
    endLine: z.number().int().positive(),
    excerptSha256: sha256,
  })
  .strict()
  .refine((semantic) => semantic.startLine <= semantic.endLine, "a line span must run forward");

const modelSchema = z
  .object({
    simcCommit: commit,
    gameDataBuild: z.string().regex(/^\d+\.\d+\.\d+\.\d+$/),
    commitDate: z.string().min(1),
    semantics: z.array(semanticSchema).min(1),
  })
  .strict();

const profileFileSchema = z
  .object({
    path: z.string().min(1),
    sha256,
    /** Every option line that would set the environment, verbatim. Any entry refuses the record. */
    environmentOptionLines: z.array(z.string().min(1)),
  })
  .strict();

const specializationSchema = z
  .object({
    aplAuthorityId: z.string().min(1),
    profiles: z.array(profileFileSchema).min(1),
  })
  .strict();

export const simcProfileEnvironmentSchema = z
  .object({
    artifactVersion: z.literal(1),
    datasetId: z.literal("SIMC_PROFILE_ENVIRONMENT"),
    datasetRevision: z.string().min(1),
    generatorRevision: z.number().int().positive(),
    extractedOn: z.string().min(1),
    source: z
      .object({
        repository: z.string().min(1),
        analyzerPin: commit,
        profileDirectory: z.string().min(1),
      })
      .strict(),
    engineDefaultEnvironment: z
      .object({
        fightStyle: z.string().min(1),
        targetCount: z.number().int().positive(),
        raidEventCount: z.number().int().nonnegative(),
        distanceTargetingEnabled: z.boolean(),
      })
      .strict(),
    models: z.array(modelSchema).min(1),
    specializations: z.array(specializationSchema).min(1),
  })
  .strict();

export type SimcProfileEnvironmentDataset = z.infer<typeof simcProfileEnvironmentSchema>;
export type SimcProfileModel = SimcProfileEnvironmentDataset["models"][number];
export type SimcProfileSemantic = SimcProfileModel["semantics"][number];
export type SimcProfileSpecialization = SimcProfileEnvironmentDataset["specializations"][number];

function loadCommitted(): SimcProfileEnvironmentDataset {
  const parsed = simcProfileEnvironmentSchema.safeParse(artifact);
  if (!parsed.success) {
    throw new Error(`the pinned SimC profile environment does not validate: ${parsed.error.message}`);
  }
  return parsed.data;
}

export const SIMC_PROFILE_ENVIRONMENT: SimcProfileEnvironmentDataset = loadCommitted();
